// One queue, every service.
type Queue[T any] struct{ jobs chan T }

func NewQueue[T any](size, workers int, handle func(T)) *Queue[T] {
    q := &Queue[T]{jobs: make(chan T, size)}
    for i := 0; i < workers; i++ {
        go func() {
            for job := range q.jobs {
                handle(job)
            }
        }()
    }
    return q
}

// Push blocks when the queue is full: back-pressure, not endless memory.
func (q *Queue[T]) Push(job T) { q.jobs <- job }

function claim() external {
    uint256 amount = rewards[msg.sender];
    require(amount > 0, "nothing to claim");

    rewards[msg.sender] = 0; // effects first
    token.safeTransfer(msg.sender, amount); // interaction last
}

// Ask for the pins inside the current view, nothing else.
map.on("moveend", async () => {
  const b = map.getBounds();
  const pins = await fetchPins({
    south: b.getSouth(),
    west: b.getWest(),
    north: b.getNorth(),
    east: b.getEast(),
  });
  cluster.clearLayers();
  cluster.addLayers(pins.map(toMarker));
});
